def _build_trading_context(
    df: pd.DataFrame,
) -> str:
    """
    Construye un resumen pequeño de las operaciones
    para enviarlo al chat de IA.
    """

    initial_capital = float(
        st.session_state.get(
            "capital_actual",
            10000.0,
        )
    )

    summary = calculate_summary(
        df,
        initial_capital,
    )

    context = f"""
Resumen de la cuenta del trader:

Capital inicial: {initial_capital}
Balance actual: {summary.get("balance", initial_capital)}
PnL acumulado: {summary.get("pnl", 0)}
Total de trades: {summary.get("total", 0)}
Ganadores: {summary.get("wins", 0)}
Perdedores: {summary.get("losses", 0)}
Break even: {summary.get("break_even", 0)}
Win rate: {summary.get("win_rate", 0):.2f}%
Profit factor: {summary.get("profit_factor", 0):.2f}
R:R promedio: {summary.get("average_rr", 0):.2f}
Drawdown máximo: {summary.get("drawdown_percent", 0):.2f}%
Ganancia promedio: {summary.get("average_win", 0):.2f}
Pérdida promedio: {summary.get("average_loss", 0):.2f}
Mejor trade: {summary.get("best_trade", 0):.2f}
Peor trade: {summary.get("worst_trade", 0):.2f}
"""

    if not df.empty:

        recent_columns = [
            column
            for column in [
                "fecha",
                "par",
                "direccion",
                "resultado",
                "beneficio_usd",
                "rr",
                "emocion",
                "notas_emocionales",
            ]
            if column in df.columns
        ]

        recent = (
            df.sort_values(
                [
                    "fecha_dt",
                    "created_at_dt",
                ],
                ascending=False,
            )
            .head(10)
        )

        context += (
            "\nÚltimas operaciones:\n"
            + recent[
                recent_columns
            ].to_string(
                index=False
            )
        )

    return context


def _ask_openrouter(
    prompt: str,
    context: str,
) -> str:
    """
    Envía una pregunta a OpenRouter.
    """

    if not OPENROUTER_API_KEY:

        raise RuntimeError(
            "OPENROUTER_API_KEY no está configurada "
            "en Streamlit Secrets."
        )

    headers = {
        "Authorization":
            f"Bearer {OPENROUTER_API_KEY}",

        "Content-Type":
            "application/json",

        "HTTP-Referer":
            "https://streamlit.io",

        "X-Title":
            "AXION PRIME X10 PRO",
    }

    system_message = """
Eres AXION Coach, un auditor profesional de trading.

Analiza solamente los datos suministrados por el diario
del usuario.

Debes responder en español, con claridad y sin exagerar.

No prometas rentabilidad.
No inventes datos que no aparezcan en el contexto.
No des señales de compra o venta.
No indiques que una operación futura está garantizada.

Tu misión es ayudar al trader a detectar:

- errores de disciplina;
- patrones emocionales;
- problemas de gestión de riesgo;
- activos con mejor o peor desempeño;
- fortalezas de su sistema;
- acciones concretas para mejorar.

Usa explicaciones sencillas, pero profesionales.
"""

    payload = {
        "model": OPENROUTER_MODEL,
        "temperature": 0.3,
        "max_tokens": 1200,
        "messages": [
            {
                "role": "system",
                "content": system_message,
            },
            {
                "role": "user",
                "content": (
                    context
                    + "\n\nPregunta del trader:\n"
                    + prompt
                ),
            },
        ],
    }

    try:

        response = requests.post(
            "https://openrouter.ai/api/v1/chat/completions",
            headers=headers,
            json=payload,
            timeout=90,
        )

    except requests.Timeout as exc:

        raise RuntimeError(
            "La IA tardó demasiado en responder."
        ) from exc

    except requests.ConnectionError as exc:

        raise RuntimeError(
            "No se pudo conectar con OpenRouter."
        ) from exc

    if response.status_code != 200:

        raise RuntimeError(
            f"OpenRouter HTTP {response.status_code}: "
            f"{response.text[:700]}"
        )

    try:

        payload_response = response.json()

    except ValueError as exc:

        raise RuntimeError(
            "OpenRouter devolvió una respuesta inválida."
        ) from exc

    choices = payload_response.get(
        "choices",
        [],
    )

    if not choices:

        raise RuntimeError(
            "OpenRouter no devolvió una respuesta."
        )

    content = (
        choices[0]
        .get("message", {})
        .get("content", "")
    )

    if isinstance(content, list):

        content = "\n".join(
            str(item.get("text", ""))
            if isinstance(item, dict)
            else str(item)
            for item in content
        )

    answer = str(
        content
    ).strip()

    if not answer:

        raise RuntimeError(
            "La IA devolvió una respuesta vacía."
        )

    return answer


def render_chat(
    df: pd.DataFrame,
) -> None:
    """
    Chat futurista con foto real del usuario y avatar de AXION Coach.
    """

    st.markdown(
        CHAT_CSS,
        unsafe_allow_html=True,
    )

    _section_header(
        "AXION PRIME · AI COACH",
        "Chat IA",
        (
            "Consulta patrones de rendimiento, disciplina, "
            "riesgo y psicología utilizando los datos "
            "reales de tu journal."
        ),
    )

    st.html(
        """
        <section class="ax-chat-shell">
            <div class="ax-chat-status">
                <strong>AXION Coach · Neural Trading Intelligence</strong>
                <span>IA ACTIVA</span>
            </div>
            <div class="ax-chat-hint">
                Analiza disciplina, riesgo, emociones y rendimiento utilizando
                exclusivamente los datos reales de tu journal.
            </div>
        </section>

        <div class="ax-quick-grid">
            <div class="ax-quick-card" style="--card-rgb:39,216,255">
                <strong>◎ DISCIPLINA</strong>
                Detecta si estás respetando tus reglas y tu plan operativo.
            </div>

            <div class="ax-quick-card" style="--card-rgb:171,74,255">
                <strong>◇ RIESGO</strong>
                Revisa pérdidas, exposición, drawdown y consistencia.
            </div>

            <div class="ax-quick-card" style="--card-rgb:255,74,204">
                <strong>◉ PSICOLOGÍA</strong>
                Relaciona emociones, decisiones y resultados.
            </div>

            <div class="ax-quick-card" style="--card-rgb:49,255,156">
                <strong>↗ RENDIMIENTO</strong>
                Identifica fortalezas, patrones y debilidades reales.
            </div>
        </div>

        <div class="ax-chat-divider">CENTRO DE CONVERSACIÓN</div>
        """
    )

    if "chat_history" not in st.session_state:
        st.session_state.chat_history = []

    user_avatar = _resolve_user_avatar()
    ai_avatar = _resolve_ai_avatar()

    if df.empty:
        st.info(
            "Registra operaciones para que AXION Coach "
            "pueda analizar tu rendimiento."
        )

    for message in st.session_state.chat_history:
        role = message.get("role", "assistant")
        content = message.get("content", "")
        message_time = message.get("time", "")
        avatar = user_avatar if role == "user" else ai_avatar

        with st.chat_message(
            role,
            avatar=avatar,
        ):
            st.caption(
                (
                    f"TÚ · {message_time}"
                    if role == "user"
                    else f"AXION COACH · {message_time}"
                ).rstrip(" ·")
            )
            st.markdown(content)

    prompt = st.chat_input(
        "Pregunta sobre tu operativa..."
    )

    if not prompt:
        return

    current_time = _message_time()

    st.session_state.chat_history.append(
        {
            "role": "user",
            "content": prompt,
            "time": current_time,
        }
    )

    with st.chat_message(
        "user",
        avatar=user_avatar,
    ):
        st.caption(f"TÚ · {current_time}")
        st.markdown(prompt)

    with st.chat_message(
        "assistant",
        avatar=ai_avatar,
    ):
        assistant_time = _message_time()
        st.caption(f"AXION COACH · {assistant_time}")

        if df.empty:
            answer = (
                "Todavía no hay operaciones suficientes "
                "para realizar una auditoría basada en datos."
            )
            st.markdown(answer)

        else:
            try:
                context = _build_trading_context(df)

                with st.spinner(
                    "AXION Coach está analizando tus datos..."
                ):
                    answer = _ask_openrouter(
                        prompt,
                        context,
                    )

                st.markdown(answer)

            except Exception as exc:
                answer = (
                    "No pude completar el análisis: "
                    f"{exc}"
                )
                st.error(answer)

    st.session_state.chat_history.append(
        {
            "role": "assistant",
            "content": answer,
            "time": assistant_time,
        }
    )


# =========================================================
# PSICOTRADING
# =========================================================


def render_psychology(
    df: pd.DataFrame,
) -> None:
    """
    Panel de psicotrading basado en las emociones
    registradas en las operaciones.
    """

    _section_header(
        "AXION PRIME · BEHAVIOR INTELLIGENCE",
        "Psicotrading",
        (
            "Relaciona emociones, decisiones y resultados "
            "para identificar los comportamientos que "
            "fortalecen o destruyen tu consistencia."
        ),
    )

    reflection = st.text_area(
        "Reflexión de la sesión",
        height=160,
        placeholder=(
            "¿Cómo te sentiste hoy? ¿Seguiste tu plan? "
            "¿Operaste por impulso, miedo o FOMO?"
        ),
        key="psychology_reflection",
    )

    if st.button(
        "💾 Guardar reflexión en esta sesión",
        use_container_width=True,
        key="save_session_reflection",
    ):

        st.session_state.last_reflection = (
            reflection
        )

        st.success(
            "Reflexión guardada durante esta sesión."
        )

    st.markdown("---")

    if df.empty:

        st.info(
            "Registra trades con estados emocionales "
            "para desbloquear este panel."
        )

        return

    emotion_df = pnl_by_emotion(
        df
    )

    if emotion_df.empty:

        st.info(
            "Las operaciones guardadas todavía no incluyen "
            "información emocional."
        )

        return

    total_trades = int(
        emotion_df[
            "trades"
        ].sum()
    )

    best_row = emotion_df.sort_values(
        "pnl_total",
        ascending=False,
    ).iloc[0]

    worst_row = emotion_df.sort_values(
        "pnl_total",
        ascending=True,
    ).iloc[0]

    metrics = st.columns(4)

    metrics[0].metric(
        "Trades analizados",
        total_trades,
    )

    metrics[1].metric(
        "Estados detectados",
        len(emotion_df),
    )

    metrics[2].metric(
        "Mejor estado",
        str(
            best_row.get(
                "emocion",
                "-",
            )
        ),
        _money(
            best_row.get(
                "pnl_total"
            )
        ),
    )

    metrics[3].metric(
        "Estado de mayor pérdida",
        str(
            worst_row.get(
                "emocion",
                "-",
            )
        ),
        _money(
            worst_row.get(
                "pnl_total"
            )
        ),
    )

    fig = px.bar(
        emotion_df,
        x="emocion",
        y="pnl_total",
        hover_data=[
            "trades",
            "pnl_promedio",
        ],
        title="PnL acumulado por estado emocional",
    )

    fig.update_layout(
        template="plotly_dark",
        height=420,
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(5,10,27,.78)",
        xaxis_title="Estado emocional",
        yaxis_title="PnL",
    )

    st.plotly_chart(
        fig,
        use_container_width=True,
        config={
            "displayModeBar": False,
        },
    )

    st.dataframe(
        emotion_df,
        use_container_width=True,
        hide_index=True,
    )


