def render_analysis() -> None:
    """
    Auditor visual independiente para capturas
    de TradingView.
    """

    _section_header(
        "AXION PRIME · VISION ENGINE",
        "Análisis IA",
        (
            "Extrae parámetros visibles de una captura "
            "de TradingView sin guardarla como operación."
        ),
    )

    chart = st.file_uploader(
        "Subir captura del gráfico",
        type=[
            "png",
            "jpg",
            "jpeg",
            "webp",
        ],
        key="analysis_chart",
    )

    if chart is None:

        st.info(
            "Sube una captura para activar el análisis."
        )

        return

    st.image(
        chart,
        caption="Captura seleccionada",
        use_container_width=True,
    )

    if not st.button(
        "🔍 ANALIZAR CAPTURA",
        use_container_width=True,
        key="analysis_scan_button",
    ):

        return

    try:

        with st.spinner(
            "AXION Vision está leyendo el gráfico..."
        ):

            result = scan_trade(
                chart.getvalue(),
                chart.type
                or "image/jpeg",
            )

        st.success(
            "Lectura visual completada."
        )

        metrics = st.columns(4)

        metrics[0].metric(
            "Activo",
            result.get("asset")
            or "No detectado",
        )

        metrics[1].metric(
            "Dirección",
            result.get("direction")
            or "No detectada",
        )

        metrics[2].metric(
            "Entrada",
            result.get("entry")
            if result.get("entry") is not None
            else "No detectada",
        )

        metrics[3].metric(
            "Confianza",
            f"{_safe_float(result.get('confidence')):.0f}%",
        )

        secondary = st.columns(3)

        secondary[0].metric(
            "Stop Loss",
            result.get("sl")
            if result.get("sl") is not None
            else "No detectado",
        )

        secondary[1].metric(
            "Take Profit",
            result.get("tp")
            if result.get("tp") is not None
            else "No detectado",
        )

        secondary[2].metric(
            "Timeframe",
            result.get("timeframe")
            or "No detectado",
        )

        with st.expander(
            "Ver JSON completo"
        ):

            st.json(
                result
            )

    except VisionError as exc:

        st.error(
            f"No se pudo analizar la captura: {exc}"
        )

    except Exception as exc:

        st.error(
            f"Error inesperado: {exc}"
        )


# =========================================================
# PROYECCIONES
# =========================================================


def render_projections() -> None:
    """
    Calculadora de expectativa y proyección de capital.
    """

    _section_header(
        "AXION PRIME · EXPECTANCY LAB",
        "Proyecciones",
        (
            "Simula escenarios matemáticos basados en "
            "win rate, riesgo, frecuencia y ratio R:R."
        ),
    )

    left, right = st.columns(2)

    with left:

        capital = st.number_input(
            "Capital inicial",
            min_value=0.0,
            value=float(
                st.session_state.get(
                    "capital_actual",
                    10000.0,
                )
            ),
            step=100.0,
            key="projection_capital",
        )

        trades_month = st.slider(
            "Operaciones por mes",
            min_value=1,
            max_value=100,
            value=20,
            key="projection_trades_month",
        )

        months = st.slider(
            "Meses de proyección",
            min_value=1,
            max_value=36,
            value=12,
            key="projection_months",
        )

    with right:

        win_rate = st.slider(
            "Win rate estimado (%)",
            min_value=1,
            max_value=99,
            value=55,
            key="projection_win_rate",
        )

        average_rr = st.number_input(
            "R:R promedio",
            min_value=0.1,
            value=2.0,
            step=0.1,
            key="projection_average_rr",
        )

        risk_percent = st.number_input(
            "Riesgo por operación (%)",
            min_value=0.01,
            max_value=20.0,
            value=1.0,
            step=0.1,
            key="projection_risk",
        )

    probability_win = (
        win_rate
        / 100
    )

    probability_loss = (
        1
        - probability_win
    )

    expectancy_r = (
        probability_win
        * average_rr
        -
        probability_loss
    )

    expected_monthly_percent = (
        expectancy_r
        * risk_percent
        * trades_month
    )

    expected_monthly_money = (
        capital
        * expected_monthly_percent
        / 100
    )

    projected_capital = (
        capital
        * (
            1
            + expected_monthly_percent
            / 100
        ) ** months
    )

    metrics = st.columns(4)

    metrics[0].metric(
        "Expectativa por trade",
        f"{expectancy_r:.2f}R",
    )

    metrics[1].metric(
        "Expectativa mensual",
        f"{expected_monthly_percent:.2f}%",
    )

    metrics[2].metric(
        "Resultado mensual estimado",
        _money(
            expected_monthly_money
        ),
    )

    metrics[3].metric(
        f"Capital proyectado ({months} meses)",
        _money(
            projected_capital
        ),
    )

    projection_rows = []

    current_capital = float(
        capital
    )

    for month in range(
        1,
        months + 1,
    ):

        current_capital *= (
            1
            + expected_monthly_percent
            / 100
        )

        projection_rows.append(
            {
                "Mes": month,
                "Capital proyectado":
                    current_capital,
            }
        )

    projection_df = pd.DataFrame(
        projection_rows
    )

    fig = px.line(
        projection_df,
        x="Mes",
        y="Capital proyectado",
        markers=True,
        title="Proyección matemática del capital",
    )

    fig.update_layout(
        template="plotly_dark",
        height=430,
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(5,10,27,.78)",
    )

    st.plotly_chart(
        fig,
        use_container_width=True,
        config={
            "displayModeBar": False,
        },
    )

    st.warning(
        "Esta proyección es matemática y no representa "
        "una garantía de resultados futuros."
    )


